import { forwardRef } from 'react';
import { Icon } from '../Icon';
import type { CheckboxProps } from './Checkbox.types';

import { cn } from '../../internal/cn';

/**
 * Checkbox.
 *
 * Figma 정의 (node 80:1401):
 *   - 외곽 24×24, radius 6
 *   - default: bg white, border 1px neutral-400
 *   - active(checked): bg primary, border 없음, 가운데 흰색 check 아이콘 (18×18)
 *
 * 사용:
 *   const [v, setV] = useState(false);
 *   <Checkbox checked={v} onChange={(e) => setV(e.target.checked)}>약관 동의</Checkbox>
 */
export const Checkbox = forwardRef<HTMLInputElement, CheckboxProps>(
  function Checkbox({ checked, children, className, disabled, ...rest }, ref) {
    return (
      <label
        className={cn(
          'inline-flex items-center gap-8 select-none',
          disabled ? 'cursor-not-allowed' : 'cursor-pointer',
          className
        )}
      >
        <span
          className={cn(
            'relative inline-flex items-center justify-center rounded-checkbox-6 border',
            checked
              ? 'bg-primary border-primary'
              : 'bg-neutral-white border-neutral-400'
          )}
          style={{ width: 24, height: 24 }}
        >
          <input
            ref={ref}
            type="checkbox"
            className="sr-only"
            checked={checked}
            disabled={disabled}
            {...rest}
          />
          {checked && (
            <Icon name="check" size={18} className="text-neutral-white" />
          )}
        </span>
        {children && (
          <span className="text-body-sm-16 text-neutral-800">{children}</span>
        )}
      </label>
    );
  }
);

Checkbox.displayName = 'IDS.Checkbox';
