import { create } from 'zustand';
import type { AlertOptions, ConfirmOptions, ModalEntry } from './Modal.types';

interface ModalState {
  stack: ModalEntry[];
  push: (entry: Omit<ModalEntry, 'id'>) => string;
  closeById: (id: string, value?: boolean) => void;
}

const uid = () => Math.random().toString(36).slice(2, 10);

export const useModalStore = create<ModalState>((set, get) => ({
  stack: [],
  push: (entry) => {
    const id = uid();
    set((state) => ({ stack: [...state.stack, { ...entry, id } as ModalEntry] }));
    return id;
  },
  closeById: (id, value = false) => {
    const entry = get().stack.find((e) => e.id === id);
    if (!entry) return;
    if (entry.kind === 'alert') entry.resolve();
    else entry.resolve(value);
    set((state) => ({ stack: state.stack.filter((e) => e.id !== id) }));
  },
}));

export const modal = {
  alert: (options: AlertOptions): Promise<void> =>
    new Promise<void>((resolve) => {
      useModalStore.getState().push({ kind: 'alert', options, resolve });
    }),
  confirm: (options: ConfirmOptions): Promise<boolean> =>
    new Promise<boolean>((resolve) => {
      useModalStore.getState().push({ kind: 'confirm', options, resolve });
    }),
};
