import { forwardRef } from 'react';
import { cn } from '../../internal/cn';
import type { CarTitleProps } from './CarTitle.types';

export const CarTitle = forwardRef<HTMLDivElement, CarTitleProps>(function CarTitle(
  { carModel, plateNumber, width, full = true, className, style, ...rest },
  ref
) {
  return (
    <div
      ref={ref}
      className={cn(
        'flex flex-col gap-8 p-16 bg-neutral-white border border-neutral-200 rounded-lg-12',
        full ? 'w-full' : 'self-start',
        className
      )}
      style={{ width, ...style }}
      {...rest}
    >
      <span className="text-body-sm-16 font-regular text-neutral-black">
        {carModel}
      </span>
      <span className="text-h1-24 font-bold text-neutral-black">
        {plateNumber}
      </span>
    </div>
  );
});

CarTitle.displayName = 'IDS.CarTitle';
