import { forwardRef } from 'react';
import { Icon } from '../Icon';
import type { InfoProps } from './Info.types';

import { cn } from '../../internal/cn';

/**
 * Info.
 *
 * Figma 정의 (node 2:367):
 *   - bg neutral-100, border neutral-200, radius 12, padding 16, vertical gap 8
 *   - 헤더: icon 20 + 14 SemiBold primary, gap 2
 *   - 본문: 16 Regular black, line-height 1.5
 *
 * 시스템 안내문(유의 사항·주의)에 사용. 사용자가 적은 메모는 `Memo` 사용.
 */
export const Info = forwardRef<HTMLDivElement, InfoProps>(function Info(
  { icon = 'info', title, children, className, ...rest },
  ref
) {
  return (
    <div
      ref={ref}
      className={cn(
        'flex flex-col gap-8 w-full bg-neutral-100 border border-neutral-200 rounded-lg-12 p-16',
        className
      )}
      {...rest}
    >
      <div className="flex items-center gap-4">
        <Icon name={icon} size={20} filled className="text-primary" />
        <span className="text-micro-14 font-semibold text-primary">
          {title}
        </span>
      </div>
      <p className="text-body-sm-16 font-regular text-neutral-black leading-base">
        {children}
      </p>
    </div>
  );
});

Info.displayName = 'IDS.Info';
