import { forwardRef } from 'react';
import { Icon } from '../Icon';
import { cn } from '../../internal/cn';
import type { StatusPillProps, StatusPillStatus } from './StatusPill.types';

const COLOR: Record<StatusPillStatus, string> = {
  completed: 'text-success',
  'in-progress': 'text-primary',
  pending: 'text-neutral-500',
  failed: 'text-danger',
  operated: 'text-neutral-600',
};

const DEFAULT_LABEL: Record<StatusPillStatus, string> = {
  completed: '완료',
  'in-progress': '진행중...',
  pending: '대기',
  failed: '실패',
  operated: '운영 완료',
};

export const StatusPill = forwardRef<HTMLSpanElement, StatusPillProps>(
  function StatusPill({ status, className, children, ...rest }, ref) {
    return (
      <span
        ref={ref}
        className={cn(
          'inline-flex items-center gap-4 text-caption-15 font-bold whitespace-nowrap',
          COLOR[status],
          className
        )}
        {...rest}
      >
        <span>{children ?? DEFAULT_LABEL[status]}</span>
        {(status === 'completed' || status === 'operated') && (
          <Icon name="check_circle" size={24} filled />
        )}
        {status === 'pending' && <Icon name="clock_loader_10" size={24} />}
        {status === 'failed' && <Icon name="cancel" size={24} filled />}
      </span>
    );
  }
);
StatusPill.displayName = 'IDS.StatusPill';
