import { create } from 'zustand';
import type { ToastEntry, ToastOptions, ToastTone } from './Toast.types';

interface ToastState {
  stack: ToastEntry[];
  push: (entry: Omit<ToastEntry, 'id'>) => string;
  /** id 항목을 exit 단계로 마크 → EXIT_DURATION 후 실제 제거. */
  remove: (id: string) => void;
}

const uid = () => Math.random().toString(36).slice(2, 10);
const EXIT_DURATION = 200;

const useToastStore = create<ToastState>((set) => ({
  stack: [],
  push: (entry) => {
    const id = uid();
    set((s) => ({ stack: [...s.stack, { ...entry, id }] }));
    return id;
  },
  remove: (id) => {
    set((s) => ({
      stack: s.stack.map((e) => (e.id === id ? { ...e, exiting: true } : e)),
    }));
    setTimeout(() => {
      set((s) => ({ stack: s.stack.filter((e) => e.id !== id) }));
    }, EXIT_DURATION);
  },
}));

export { useToastStore };

const DEFAULT_DURATION = 3000;
const DEFAULT_POSITION = 'top-center';

const show = (variant: ToastTone, options: ToastOptions): string => {
  const duration = options.duration ?? DEFAULT_DURATION;
  const id = useToastStore.getState().push({
    variant,
    title: options.title,
    description: options.description,
    duration,
    position: options.position ?? DEFAULT_POSITION,
  });
  if (duration > 0) {
    setTimeout(() => useToastStore.getState().remove(id), duration);
  }
  return id;
};

export const toast = {
  success: (options: ToastOptions) => show('success', options),
  error: (options: ToastOptions) => show('error', options),
  /** 특정 toast 수동 dismiss (exit 애니메이션 거쳐 사라짐). */
  dismiss: (id: string) => useToastStore.getState().remove(id),
};
