import { forwardRef } from 'react';
import type { RadioProps } from './Radio.types';

import { cn } from '../../internal/cn';

/**
 * Radio.
 *
 * Figma 정의 (node 5:1326):
 *   - 외곽 24×24, 안쪽 dot 14×14 (이전 15 → 14, 짝수 여백으로 서브픽셀 정렬 해결)
 *   - default border: neutral-400
 *   - active(checked) border: button-primary-default
 *   - active 안쪽 dot: button-primary-default
 *
 * 사용:
 *   const [val, setVal] = useState('a');
 *   <Radio name="opt" value="a" checked={val === 'a'} onChange={(e) => setVal(e.target.value)}>옵션 A</Radio>
 */
export const Radio = forwardRef<HTMLInputElement, RadioProps>(function Radio(
  { checked, children, className, disabled, ...rest },
  ref
) {
  return (
    <label
      className={cn(
        'inline-flex items-center gap-8 select-none',
        disabled ? 'cursor-not-allowed' : 'cursor-pointer',
        className
      )}
    >
      <span
        className={cn(
          'relative inline-flex items-center justify-center rounded-pill-999 border bg-neutral-white',
          checked ? 'border-button-primary-default' : 'border-neutral-400'
        )}
        style={{ width: 24, height: 24 }}
      >
        <input
          ref={ref}
          type="radio"
          className="sr-only"
          checked={checked}
          disabled={disabled}
          {...rest}
        />
        {checked && (
          <span
            className="rounded-pill-999 bg-button-primary-default"
            style={{ width: 14, height: 14 }}
          />
        )}
      </span>
      {children && (
        <span className="text-body-sm-16 text-neutral-800">{children}</span>
      )}
    </label>
  );
});
