import { forwardRef } from 'react';
import { Icon } from '../Icon';
import type { InputProps } from './Input.types';

import { cn } from '../../internal/cn';

/**
 * Input — 단일 라인 텍스트 입력 (Figma 0:280 type=Text).
 *
 * 명세:
 *   - 라벨 14 Regular #66666e + required asterisk(danger)
 *   - 박스 h 48, radius input-10, padding x 16, gap 8
 *   - default/filled: bg white, border neutral-200
 *   - disabled: bg neutral-100, text neutral-600
 *   - error: border danger + trailing error icon
 *   - success: border success + trailing check_circle icon
 *   - focus: focus-within으로 정의된 ring(shadow) 추가
 */
export const Input = forwardRef<HTMLInputElement, InputProps>(function Input(
  { label, required, error, success, disabled, onClear, className, ...rest },
  ref
) {
  const stateClass = error
    ? 'border-danger'
    : success
      ? 'border-success'
      : 'border-neutral-200';
  const bgClass = disabled ? 'bg-neutral-100' : 'bg-neutral-white';
  const textClass = disabled ? 'text-neutral-600' : 'text-neutral-black';

  const hasValue = rest.value != null && String(rest.value).length > 0;
  const showClear =
    !!onClear && hasValue && !disabled && !error && !success;

  return (
    <label className={cn('flex flex-col gap-8 w-full', className)}>
      {label && (
        <span className="flex items-center gap-2 text-micro-14 font-regular text-neutral-600">
          <span>{label}</span>
          {required && <span className="text-danger">*</span>}
        </span>
      )}
      <span
        className={cn(
          'flex items-center gap-8 h-[48px] px-16 border rounded-input-10',
          'focus-within:shadow-[0_0_0_3px_rgba(38,57,73,0.08)]',
          stateClass,
          bgClass
        )}
      >
        <input
          ref={ref}
          disabled={disabled}
          className={cn(
            'flex-1 min-w-0 bg-transparent outline-none border-0 p-0 text-body-sm-16 font-regular placeholder:text-neutral-500',
            textClass
          )}
          {...rest}
        />
        {showClear && (
          <button
            type="button"
            aria-label="입력 지우기"
            onMouseDown={(e) => e.preventDefault()}
            onClick={onClear}
            className="inline-flex items-center justify-center text-neutral-500 hover:text-neutral-600"
          >
            <Icon name="cancel" size={24} filled />
          </button>
        )}
        {error && <Icon name="error" size={24} filled className="text-danger" />}
        {success && (
          <Icon name="check_circle" size={24} filled className="text-success" />
        )}
      </span>
    </label>
  );
});

Input.displayName = 'IDS.Input';
