import { forwardRef } from 'react';
import { StatusPill } from '../StatusPill';
import { cn } from '../../internal/cn';
import type { VerificationItemProps } from './VerificationItem.types';

/**
 * VerificationItem — 검증 진행 리스트 행 (Figma node 8:1042).
 *
 * - row: w-full, gap 8, py 4
 * - title: text-caption-15 font-bold text-neutral-black, ellipsis
 * - 우측: StatusPill (status별 색·아이콘 자동)
 * - status별 라벨 텍스트는 *Label prop 으로 override 가능 (미지정 시 StatusPill 의 기본 라벨 사용)
 */
export const VerificationItem = forwardRef<HTMLDivElement, VerificationItemProps>(
  function VerificationItem(
    {
      title,
      status,
      pendingLabel,
      inProgressLabel,
      completedLabel,
      failedLabel,
      className,
      ...rest
    },
    ref
  ) {
    const overrideLabel =
      status === 'pending'
        ? pendingLabel
        : status === 'in-progress'
          ? inProgressLabel
          : status === 'completed'
            ? completedLabel
            : failedLabel;

    return (
      <div
        ref={ref}
        className={cn('flex items-center gap-8 w-full py-4', className)}
        {...rest}
      >
        <span className="text-caption-15 font-bold text-neutral-black flex-1 min-w-0 truncate">
          {title}
        </span>
        <StatusPill status={status}>{overrideLabel}</StatusPill>
      </div>
    );
  }
);
VerificationItem.displayName = 'IDS.VerificationItem';
