import { forwardRef } from 'react';
import { Icon } from '../Icon';
import type { ListItemProps } from './ListItem.types';

import { cn } from '../../internal/cn';

/**
 * ListItem.
 *
 * Figma 정의 (node 0:420 "List"):
 *   - w-full, radius 12, padding 24/16, border 1
 *   - title: 17 Bold black (좌측)
 *   - 우측: label + icon
 *
 * Incomplete:
 *   - bg white, border neutral-200
 *   - label "미완료" 17 Bold neutral-500
 *   - icon arrow_forward_ios 20
 *
 * Completed:
 *   - bg success-bg, border success
 *   - label "완료" 17 Bold success
 *   - icon check_circle 24 (filled, success)
 */
export const ListItem = forwardRef<HTMLDivElement, ListItemProps>(
  function ListItem(
    {
      title,
      completed = false,
      incompleteLabel = '미완료',
      completedLabel = '완료',
      className,
      ...rest
    },
    ref
  ) {
    return (
      <div
        ref={ref}
        className={cn(
          'flex items-center justify-between w-full border rounded-lg-12 px-16 py-24',
          completed
            ? 'bg-success-bg border-success'
            : 'bg-neutral-white border-neutral-200',
          className
        )}
        {...rest}
      >
        <span className="text-body-17 font-bold text-neutral-black">
          {title}
        </span>
        <span className="flex items-center gap-4 shrink-0">
          {completed ? (
            <>
              <span className="text-body-17 font-bold text-success">
                {completedLabel}
              </span>
              <Icon name="check_circle" size={24} filled className="text-success" />
            </>
          ) : (
            <>
              <span className="text-body-17 font-bold text-neutral-500">
                {incompleteLabel}
              </span>
              <Icon name="arrow_forward_ios" size={20} className="text-neutral-500" />
            </>
          )}
        </span>
      </div>
    );
  }
);

ListItem.displayName = 'IDS.ListItem';
