import { useEffect, useState } from 'react';
import { createPortal } from 'react-dom';
import { Toast } from './Toast';
import { useToastStore } from './toastStore';
import { cn } from '../../internal/cn';
import { IDS_Z_INDEX } from '../../internal/zIndex';
import type { ToastEntry, ToastPosition } from './Toast.types';

const POSITION_CLASS: Record<ToastPosition, string> = {
  'top-center': 'top-80',
  center: 'top-1/2 -translate-y-1/2',
  'bottom-center': 'bottom-16',
};

const POSITIONS: ToastPosition[] = ['top-center', 'center', 'bottom-center'];

const ENTER_OFFSET_PX: Record<ToastPosition, number> = {
  'top-center': -8,
  center: 0,
  'bottom-center': 8,
};

const ANIMATION_MS = 200;

interface ToastItemProps {
  entry: ToastEntry;
}

const ToastItem = ({ entry }: ToastItemProps) => {
  const [entered, setEntered] = useState(false);

  useEffect(() => {
    const raf = requestAnimationFrame(() => setEntered(true));
    return () => cancelAnimationFrame(raf);
  }, []);

  const visible = entered && !entry.exiting;
  const offset = ENTER_OFFSET_PX[entry.position];

  return (
    <Toast
      variant={entry.variant}
      title={entry.title}
      description={entry.description}
      className="w-full pointer-events-auto"
      style={{
        opacity: visible ? 1 : 0,
        transform: visible ? 'translateY(0)' : `translateY(${offset}px)`,
        transition: `opacity ${ANIMATION_MS}ms ease-out, transform ${ANIMATION_MS}ms ease-out`,
      }}
    />
  );
};

export const Toaster = () => {
  const stack = useToastStore((s) => s.stack);
  const [mounted, setMounted] = useState(false);

  useEffect(() => setMounted(true), []);
  if (!mounted || stack.length === 0) return null;

  return createPortal(
    <>
      {POSITIONS.map((pos) => {
        const entries = stack.filter((e) => e.position === pos);
        if (entries.length === 0) return null;
        return (
          <div
            key={pos}
            className={cn(
              'fixed inset-x-16 flex flex-col items-stretch gap-8 pointer-events-none',
              POSITION_CLASS[pos]
            )}
            style={{ zIndex: IDS_Z_INDEX.TOAST }}
          >
            {entries.map((entry) => (
              <ToastItem key={entry.id} entry={entry} />
            ))}
          </div>
        );
      })}
    </>,
    document.body
  );
};

Toaster.displayName = 'IDS.Toaster';
