import { forwardRef } from 'react';
import { Icon } from '../Icon';
import { cn } from '../../internal/cn';
import type { HistoryPhotoProps } from './HistoryPhoto.types';

export const HistoryPhoto = forwardRef<HTMLDivElement, HistoryPhotoProps>(
  function HistoryPhoto(
    { width = 106, full, src, label, onRetake, className, style, ...rest },
    ref
  ) {
    return (
      <div
        ref={ref}
        className={cn(
          'relative overflow-clip aspect-square bg-neutral-black border border-neutral-200 rounded-lg-12',
          full ? 'w-full' : 'self-start',
          className
        )}
        style={{ width: full ? undefined : width, ...style }}
        {...rest}
      >
        <img
          alt=""
          src={src}
          className="absolute inset-0 size-full object-cover opacity-50 pointer-events-none"
        />
        {onRetake && (
          <button
            type="button"
            onClick={onRetake}
            aria-label="재촬영"
            className="absolute top-0 right-0 inline-flex items-center justify-center p-8 rounded-md-8 text-neutral-white"
          >
            <Icon name="flip_camera_ios" size={24} />
          </button>
        )}
        <span className="absolute inset-0 flex items-center justify-center text-micro-14 font-regular text-neutral-white text-center px-8">
          {label}
        </span>
      </div>
    );
  }
);
HistoryPhoto.displayName = 'IDS.HistoryPhoto';
