import { forwardRef } from 'react';
import { Icon } from '../Icon';
import { cn } from '../../internal/cn';
import type { ModalListItemProps } from './ModalListItem.types';

export const ModalListItem = forwardRef<HTMLButtonElement, ModalListItemProps>(
  function ModalListItem(
    { selected = false, disabled, children, className, ...rest },
    ref
  ) {
    return (
      <button
        ref={ref}
        type="button"
        disabled={disabled}
        aria-pressed={selected}
        className={cn(
          'flex items-center justify-between w-full bg-neutral-white border rounded-md-8 p-16 text-left',
          selected ? 'border-primary' : 'border-neutral-400',
          disabled ? 'cursor-not-allowed opacity-50' : 'cursor-pointer',
          className
        )}
        {...rest}
      >
        <span className="text-body-17 font-bold text-neutral-black">
          {children}
        </span>
        {selected && (
          <Icon name="check_circle" size={24} filled className="text-primary" />
        )}
      </button>
    );
  }
);

ModalListItem.displayName = 'IDS.ModalListItem';
