import { forwardRef } from 'react';
import { Icon } from '../Icon';
import type { ToastProps, ToastTone } from './Toast.types';

import { cn } from '../../internal/cn';

const TONE_CLASS: Record<ToastTone, string> = {
  success: 'bg-success-bg border-success',
  error: 'bg-error-bg border-danger',
};

const TONE_ICON_COLOR: Record<ToastTone, string> = {
  success: 'text-success',
  error: 'text-danger',
};

const TONE_ICON_NAME: Record<ToastTone, string> = {
  success: 'check_circle',
  error: 'error',
};

/**
 * Toast — 인라인 결과/안내 메시지.
 *
 * Figma 정의:
 *   - padding 16, gap 8, radius 12, border 1
 *   - icon 32x32, title body-17 Bold, description caption-15 Regular
 *   - success / error 두 가지
 *
 * (떴다 사라지는 팝업이 아니라 form/페이지 안에서 인라인 표시 용도)
 */
export const Toast = forwardRef<HTMLDivElement, ToastProps>(function Toast(
  { variant = 'success', title, description, className, ...rest },
  ref
) {
  return (
    <div
      ref={ref}
      role="status"
      className={cn(
        'flex items-center gap-8 p-16 rounded-lg-12 border text-neutral-black backdrop-blur-[2px]',
        TONE_CLASS[variant],
        className
      )}
      {...rest}
    >
      <Icon name={TONE_ICON_NAME[variant]} size={32} filled className={TONE_ICON_COLOR[variant]} />
      <div className="flex flex-col flex-1 min-w-0">
        <p className="text-body-17 font-bold">{title}</p>
        {description && (
          <p className="text-caption-15 font-regular">{description}</p>
        )}
      </div>
    </div>
  );
});
