import { forwardRef } from 'react';
import { Icon } from '../Icon';
import type { SearchProps } from './Search.types';

import { cn } from '../../internal/cn';

/**
 * Search — 검색 input (Figma 0:280 type=Search).
 *
 * 박스 h 48, radius input-10, padding x 16, gap 8.
 * 좌측 search 아이콘 24px.
 */
export const Search = forwardRef<HTMLInputElement, SearchProps>(function Search(
  { label, required, disabled, onClear, className, placeholder = 'Placeholder', ...rest },
  ref
) {
  const hasValue = rest.value != null && String(rest.value).length > 0;
  const showClear = !!onClear && hasValue && !disabled;

  return (
    <label className={cn('flex flex-col gap-8 w-full', className)}>
      {label && (
        <span className="flex items-center gap-2 text-micro-14 font-regular text-neutral-600">
          <span>{label}</span>
          {required && <span className="text-danger">*</span>}
        </span>
      )}
      <span
        className={cn(
          'flex items-center gap-8 h-[48px] px-16 border border-neutral-200 rounded-input-10',
          'focus-within:shadow-[0_0_0_3px_rgba(38,57,73,0.08)]',
          disabled ? 'bg-neutral-100' : 'bg-neutral-white'
        )}
      >
        <Icon
          name="search"
          size={24}
          className={disabled ? 'text-neutral-500' : 'text-neutral-black'}
        />
        <input
          ref={ref}
          type="search"
          disabled={disabled}
          placeholder={placeholder}
          className={cn(
            'flex-1 min-w-0 bg-transparent outline-none border-0 p-0 text-body-sm-16 font-regular placeholder:text-neutral-500',
            disabled ? 'text-neutral-600' : 'text-neutral-black'
          )}
          {...rest}
        />
        {showClear && (
          <button
            type="button"
            aria-label="입력 지우기"
            onMouseDown={(e) => e.preventDefault()}
            onClick={onClear}
            className="inline-flex items-center justify-center text-neutral-500 hover:text-neutral-600"
          >
            <Icon name="cancel" size={24} filled />
          </button>
        )}
      </span>
    </label>
  );
});

Search.displayName = 'IDS.Search';
