import { forwardRef } from 'react';
import { Icon } from '../Icon';
import type { TopAppBarProps } from './TopAppBar.types';

import { cn } from '../../internal/cn';

/**
 * Top App Bar.
 *
 * Figma 정의:
 *   - height 56, bg primary(#25313E), padding 8
 *   - title: h3-20 Bold White, 가운데
 *   - back 아이콘: 24x24, 좌측 20px
 */
export const TopAppBar = forwardRef<HTMLElement, TopAppBarProps>(function TopAppBar(
  { title, onBack, className, ...rest },
  ref
) {
  return (
    <header
      ref={ref}
      className={cn(
        'relative flex w-full items-center justify-center bg-primary p-8',
        className
      )}
      style={{ height: 56 }}
      {...rest}
    >
      {onBack && (
        <button
          type="button"
          onClick={onBack}
          aria-label="뒤로 가기"
          className="absolute top-1/2 -translate-y-1/2 inline-flex items-center justify-center text-neutral-white"
          style={{ left: 20, width: 24, height: 24 }}
        >
          <Icon name="arrow_back" size={24} filled />
        </button>
      )}
      <h1 className="text-h3-20 font-bold text-neutral-white whitespace-nowrap">
        {title}
      </h1>
    </header>
  );
});
