import { forwardRef } from 'react';
import type { TabBarItemProps, TabBarProps } from './TabBar.types';

import { cn } from '../../internal/cn';

/**
 * TabBar — 화면 하단에 고정되는 탭 컨테이너.
 *
 * Figma 정의:
 *   - bg-neutral-white, 상단 1px border-neutral-200
 *   - flex 자식 탭 균등 분할
 *
 * 사용:
 *   <TabBar>
 *     <TabBarItem active icon={<BuildIcon />}>배정 작업</TabBarItem>
 *     <TabBarItem icon={<History2Icon />}>이력</TabBarItem>
 *   </TabBar>
 */
export const TabBar = forwardRef<HTMLElement, TabBarProps>(function TabBar(
  { className, children, style, ...rest },
  ref
) {
  return (
    <nav
      ref={ref}
      className={cn(
        'fixed bottom-0 left-0 right-0 flex items-stretch justify-between bg-neutral-white border-t border-neutral-200',
        className
      )}
      style={{ zIndex: 100, ...style }}
      {...rest}
    >
      {children}
    </nav>
  );
});

/**
 * TabBarItem — TabBar의 단일 항목.
 *
 * Figma 정의:
 *   - height 70, gap 4, icon 24, text 17 Bold
 *   - active: primary, default: neutral-500
 */
export const TabBarItem = forwardRef<HTMLButtonElement, TabBarItemProps>(
  function TabBarItem({ active, icon, children, className, ...rest }, ref) {
    return (
      <button
        ref={ref}
        type="button"
        className={cn(
          'flex flex-1 flex-col items-center justify-center gap-4',
          'text-body-17 font-bold',
          active ? 'text-primary' : 'text-neutral-500',
          className
        )}
        style={{ height: 70 }}
        aria-current={active ? 'page' : undefined}
        {...rest}
      >
        {icon}
        {children}
      </button>
    );
  }
);
