import { forwardRef } from 'react';
import type { TextAreaProps } from './TextArea.types';

import { cn } from '../../internal/cn';

/**
 * TextArea — 멀티라인 입력 (Figma 0:280 type=text).
 *
 * 박스: padding 16, radius input-10, default 높이 160.
 * 텍스트: 16 Regular, line-height base.
 */
export const TextArea = forwardRef<HTMLTextAreaElement, TextAreaProps>(
  function TextArea(
    {
      label,
      required,
      error,
      success,
      disabled,
      height = 160,
      className,
      style,
      ...rest
    },
    ref
  ) {
    const stateClass = error
      ? 'border-danger'
      : success
        ? 'border-success'
        : 'border-neutral-200';
    const bgClass = disabled ? 'bg-neutral-100' : 'bg-neutral-white';
    const textClass = disabled ? 'text-neutral-600' : 'text-neutral-black';

    return (
      <label className={cn('flex flex-col gap-8 w-full', className)}>
        {label && (
          <span className="flex items-center gap-2 text-micro-14 font-regular text-neutral-600">
            <span>{label}</span>
            {required && <span className="text-danger">*</span>}
          </span>
        )}
        <span
          className={cn(
            'flex w-full p-16 border rounded-input-10',
            'focus-within:shadow-[0_0_0_3px_rgba(38,57,73,0.08)]',
            stateClass,
            bgClass
          )}
          style={{ height }}
        >
          <textarea
            ref={ref}
            disabled={disabled}
            className={cn(
              'flex-1 min-w-0 w-full bg-transparent outline-none border-0 p-0 resize-none text-body-sm-16 font-regular leading-base placeholder:text-neutral-500',
              textClass
            )}
            style={style}
            {...rest}
          />
        </span>
      </label>
    );
  }
);

TextArea.displayName = 'IDS.TextArea';
